# C2PA content credentials are stored in a JUMBF box (box type "jumb") that
# contains a manifest store labeled "c2pa". Files generated by Claude contain them, so this might catch some assets
# I'm not entirely sure if the scratch asset server strips them, but I assume it doesn't?
# This only checks if a content credential is present without validating its signature, but I don't think we need to

# I must confess that none of the ai sample projects so far had C2PA credentials, but an asset on Ninja did have a signature showing it was generated by Claude
JUMBF_BOX = b"jumb"
C2PA_LABEL = b"c2pa"


def has_c2pa(data: bytes) -> bool:
	return JUMBF_BOX in data and C2PA_LABEL in data


def check_c2pa(assets: dict[str, bytes]) -> list[str]:
	"""Takes {asset name: file bytes} and returns the names that contain C2PA credentials."""
	return [name for name, data in assets.items() if has_c2pa(data)]


def make_c2pa_report(found: list[str]) -> str:
	if not found:
		return "No C2PA content credentials found in the project assets."
	return "C2PA content credentials found in:\n" + "\n".join(f"* {name}" for name in found)

